"""Bill storage on local disk. Swap for Supabase Storage / S3 behind the same three functions."""

import uuid
from pathlib import Path

from ..config import settings


def _root() -> Path:
    root = Path(settings.upload_dir)
    root.mkdir(parents=True, exist_ok=True)
    return root


def save(data: bytes, suffix: str) -> str:
    key = f"{uuid.uuid4().hex}{suffix}"
    (_root() / key).write_bytes(data)
    return key


def path_for(key: str) -> Path:
    # Keys are generated by save(); reject anything that could walk out of the folder.
    if "/" in key or "\\" in key or ".." in key:
        raise ValueError("bad storage key")
    return _root() / key


def delete(key: str) -> None:
    path_for(key).unlink(missing_ok=True)
